$(window).scrollTop() < $(window).height() &&
  $(".nav").click(function () {
    $(window).scrollTop() == $(window).height() &&
      $("a.scrollTo").css("opacity", "0");
  });
$(".language").click()
  ? $("#menu-language").css("display", "block")
  : ($("#menu-language").css("display", "none"), $("#menu-language").hide());
$(".mobile-toggle").click(function () {
  $(".main_h").hasClass("open-nav")
    ? ($(".main_h").removeClass("open-nav"),
      $(".main_h").css("overflow", "hidden"),
      $(".mobile-toggle span").css("background", "#fff"),
      $("body").css("overflow", "auto"),
      $("#icon").show())
    : ($(".main_h").addClass("open-nav"),
      $(".main_h").css("overflow", "auto"),
      $(".mobile-toggle span").css("background", "#8ba3ba"),
      $("body").css("overflow", "hidden"),
      $("#icon").hide());
});
$(".main_h li a").click(function () {
  $(".main_h").hasClass("open-nav") &&
    ($(".navigation").removeClass("open-nav"),
    $(".main_h").removeClass("open-nav"));
});
$("nav a").click(function (b) {
  var a = $(this).attr("href");
  if ("javascript:;" === a) return !0;
  a = $(a).offset().top - 70;
  $("html, body").animate({ scrollTop: a }, 500);
  b.preventDefault();
});
